// Feb-2026 · Item 4 bonus — "Top admin questions" widget.
// Reads /api/ai/copilot/top-questions?days=30 and lets admins
// promote a common question straight into the knowledge base.
function TopQuestionsWidget({ onSaveToKnowledge }) {
  const [items, setItems] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState("");

  React.useEffect(() => {
    let alive = true;
    api.get("/ai/copilot/top-questions?days=30&limit=10")
      .then((r) => { if (alive) setItems(r?.items || []); })
      .catch((e) => { if (alive) setError(e.message || "Failed to load"); })
      .finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; };
  }, []);

  return (
    <div className="rounded-xl p-4 space-y-2"
         style={{ backgroundColor: colors.surface,
                    border: `1px solid ${colors.border}` }}
         data-testid="ai-brain-top-questions">
      <div className="flex items-center gap-2">
        <TrendingUp size={14} style={{ color: colors.brand }} />
        <div className="text-sm font-semibold" style={{ color: colors.onSurface }}>
          Top admin questions (last 30 days)
        </div>
      </div>
      {loading ? (
        <div className="text-xs" style={{ color: colors.muted }}
             data-testid="ai-brain-top-questions-loading">Loading…</div>
      ) : error ? (
        <div className="text-xs" style={{ color: "#B91C1C" }}
             data-testid="ai-brain-top-questions-error">{error}</div>
      ) : items.length === 0 ? (
        <div className="text-xs" style={{ color: colors.muted }}
             data-testid="ai-brain-top-questions-empty">
          No copilot activity yet. Try asking questions in the AI Copilot.
        </div>
      ) : (
        <div className="space-y-1"
             data-testid="ai-brain-top-questions-list">
          {items.map((q, idx) => (
            <div key={idx}
                 className="flex items-start gap-2 rounded-md p-2"
                 style={{ backgroundColor: colors.surfaceSecondary,
                            border: `1px solid ${colors.border}` }}
                 data-testid={`ai-brain-top-question-${idx}`}>
              <div className="flex-shrink-0 text-[10px] font-bold uppercase rounded px-1.5 py-0.5"
                   style={{ backgroundColor: colors.brandTertiary,
                              color: colors.brand }}>
                ×{q.count}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-xs font-semibold truncate"
                     style={{ color: colors.onSurface }}>
                  {q.prompt}
                </div>
                <div className="text-[10px]" style={{ color: colors.muted }}>
                  Last asked {(q.last_asked_at || "").slice(0, 10)}
                </div>
              </div>
              <button
                type="button"
                onClick={() => onSaveToKnowledge(q)}
                className="flex-shrink-0 flex items-center gap-1 text-[11px] font-semibold px-2 py-1 rounded-md hover:brightness-95"
                style={{ backgroundColor: colors.brand, color: "#fff" }}
                data-testid={`ai-brain-top-question-save-${idx}`}
              >
                <PlusCircle size={11} /> Add to KB
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Feb-2026 · smart enhancement — Weekly AI Employees summary tile.
// Full-width gradient hero showing what the AI has done in the
// last 7 days: drafts generated, reviews answered, latest SEO
// score, weekly star delta.
function WeeklyAIEmployeesSummary() {
  const [data, setData] = React.useState(null);
  const [card, setCard] = React.useState(null);
  const [refreshing, setRefreshing] = React.useState(false);

  const load = React.useCallback(async (bust = false) => {
    setRefreshing(true);
    try {
      const [r, c] = await Promise.all([
        api.get(`/ai/employees/weekly-summary${bust ? "?refresh=1" : ""}`),
        card ? Promise.resolve(card) : api.get("/tenants/business-card").catch(() => null),
      ]);
      setData(r);
      if (!card && c) setCard(c);
    } catch (_e) { /* graceful */ }
    finally { setRefreshing(false); }
  }, [card]);
  React.useEffect(() => { load(false); }, [load]);

  if (!data) return null;

  const from = card?.gradient_from || "#0EA5E9";
  const to = card?.gradient_to || "#16A34A";
  const grad = `linear-gradient(135deg, ${from} 0%, ${to} 100%)`;
  const rel = (iso) => {
    if (!iso) return "";
    const s = Math.round((Date.now() - new Date(iso).getTime()) / 1000);
    if (s < 60)  return `${s}s ago`;
    if (s < 3600) return `${Math.round(s / 60)}m ago`;
    return `${Math.round(s / 3600)}h ago`;
  };
  const showSeo   = data.seo_score_latest != null;
  const showDelta = data.star_delta != null;
  const deltaPositive = (data.star_delta || 0) >= 0;

  const Pill = ({ icon: Icon, label, testid }) => (
    <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-white text-xs font-semibold"
         style={{ backgroundColor: "rgba(255,255,255,0.22)",
                    border: "1px solid rgba(255,255,255,0.32)" }}
         data-testid={testid}>
      <Icon size={13} /> {label}
    </div>
  );

  return (
    <div className="rounded-2xl p-4 sm:p-5 relative overflow-hidden"
         style={{ background: grad, color: "rgba(255,255,255,0.95)" }}
         data-testid="ai-employees-weekly-summary">
      <div className="text-sm font-semibold mb-2">
        This week your AI employees did:
      </div>
      <div className="flex flex-wrap items-center gap-2">
        <Pill icon={ImageIcon}
               label={`${data.drafts_generated} draft${data.drafts_generated === 1 ? "" : "s"} generated`}
               testid="ai-week-drafts" />
        <Pill icon={MessageSquare}
               label={`${data.reviews_answered} review${data.reviews_answered === 1 ? "" : "s"} answered`}
               testid="ai-week-reviews" />
        {showSeo ? (
          <Pill icon={Gauge}
                 label={`${data.seo_score_latest}/100 SEO score`}
                 testid="ai-week-seo" />
        ) : null}
        {showDelta ? (
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold"
               style={{ backgroundColor: deltaPositive ? "#DCFCE7" : "#FEE2E2",
                          color: deltaPositive ? "#166534" : "#991B1B" }}
               data-testid="ai-week-star-delta">
            <Star size={13} fill={deltaPositive ? "#16A34A" : "#B91C1C"} />
            {deltaPositive ? "+" : ""}{data.star_delta}★ weekly delta
          </div>
        ) : null}
      </div>
      <div className="flex items-center gap-3 mt-3 text-[11px] opacity-90">
        <span data-testid="ai-week-updated">Updated {rel(data.generated_at)}.</span>
        <button
          type="button"
          onClick={() => load(true)}
          disabled={refreshing}
          className="underline flex items-center gap-1"
          data-testid="ai-week-refresh"
        >
          <RefreshCw size={10} className={refreshing ? "animate-spin" : ""} /> Refresh
        </button>
      </div>
    </div>
  );
}

// Feb-2026 · Phase 20 P2 — Admin toggle for the daily review digest.
function DailyDigestToggle() {
  const [enabled, setEnabled] = React.useState(null);
  const [saving, setSaving] = React.useState(false);
  React.useEffect(() => {
    api.get("/ai/settings/daily-review-digest")
      .then((r) => setEnabled(!!r?.enabled))
      .catch(() => setEnabled(true));
  }, []);
  const toggle = async () => {
    if (enabled === null) return;
    setSaving(true);
    try {
      const next = !enabled;
      await api.patch("/ai/settings/daily-review-digest", { enabled: next });
      setEnabled(next);
      toast.success(next ? "Daily review digest enabled" : "Digest disabled");
    } catch (e) {
      toast.error(`Toggle failed: ${e.message || e}`);
    } finally { setSaving(false); }
  };
  return (
    <div className="rounded-xl p-3 flex items-center gap-3"
         style={{ backgroundColor: colors.surface,
                    border: `1px solid ${colors.border}` }}
         data-testid="ai-brain-digest-toggle">
      <Bell size={14} style={{ color: colors.brand }} />
      <div className="flex-1 min-w-0">
        <div className="text-sm font-semibold" style={{ color: colors.onSurface }}>
          Daily review digest email
        </div>
        <div className="text-xs" style={{ color: colors.muted }}>
          Sends an 8am (Phoenix) summary of yesterday's reviews with an AI-suggested reply per row.
        </div>
      </div>
      <button
        type="button"
        onClick={toggle}
        disabled={saving || enabled === null}
        className="text-xs font-semibold px-3 py-1.5 rounded-md hover:brightness-95 disabled:opacity-60"
        style={{ backgroundColor: enabled ? colors.brand : colors.surfaceSecondary,
                   color: enabled ? "#fff" : colors.onSurface,
                   border: `1px solid ${colors.border}` }}
        data-testid="ai-brain-digest-toggle-btn"
      >
        {enabled === null ? "…" : enabled ? "On" : "Off"}
      </button>
    </div>
  );
}


// ═══════════════════════════════════════════════════════════════════
// Phase P3 · Feb-2026 · Deliverable 1 — retrieval preview panel.
//
// Debounced 300ms.  On empty query, still fetches the panel so the
// admin sees the legacy full-concat.  Retrieval metadata is surfaced
// above the preview so admins can grok which KB rows would be shown
// to Copilot for that candidate question.
// ═══════════════════════════════════════════════════════════════════
function KBRetrievalPreviewPanel() {
  const [q, setQ] = React.useState("");
  const [data, setData] = React.useState(null);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState("");

  React.useEffect(() => {
    const t = setTimeout(async () => {
      setLoading(true); setError("");
      try {
        const params = q.trim() ? `?q=${encodeURIComponent(q.trim())}` : "";
        const res = await api.get(`/ai/knowledge/system-prompt${params}`);
        setData(res);
      } catch (e) {
        setError(e?.message || "Preview failed");
        setData(null);
      } finally {
        setLoading(false);
      }
    }, 300);
    return () => clearTimeout(t);
  }, [q]);

  const retrieved = data?.retrieved || [];
  const isRag = !!(q.trim());
  const summary = isRag
    ? `Retrieved ${retrieved.length} snippet${retrieved.length === 1 ? "" : "s"} from ${data?.kb_row_count ?? "?"} KB rows.`
    : `No query — showing the legacy full-concat preview (${data?.kb_row_count ?? "?"} active KB rows).`;

  return (
    <div className="rounded-xl p-3 mt-3"
         style={{ backgroundColor: colors.surface, border: `1px solid ${colors.border}` }}
         data-testid="kb-preview-panel">
      <div className="flex items-center justify-between mb-2 flex-wrap gap-2">
        <div>
          <div className="text-sm font-semibold" style={{ color: colors.onSurface }}>
            System prompt preview
          </div>
          <div className="text-[11px]" style={{ color: colors.muted }}>
            Preview what Copilot would see for a candidate question.
          </div>
        </div>
        <input
          type="search"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Preview retrieval for a candidate question…"
          className="text-sm rounded-md px-2 py-1.5 w-full sm:w-96"
          style={{
            backgroundColor: colors.surfaceSecondary,
            color: colors.onSurface,
            border: `1px solid ${colors.border}`,
          }}
          data-testid="kb-preview-q-input"
        />
      </div>
      <div className="text-xs mb-2" style={{ color: colors.muted }}
           data-testid="kb-preview-retrieved-count">
        {loading ? "Loading preview…" : summary}
      </div>
      {isRag && retrieved.length > 0 && (
        <div className="flex flex-wrap gap-1 mb-2"
             data-testid="kb-preview-retrieved-list">
          {retrieved.map((r) => (
            <span
              key={r.id}
              className="inline-flex items-center gap-1 text-[10px] font-semibold px-2 py-0.5 rounded-full"
              style={{ backgroundColor: colors.brandTertiary, color: colors.brand }}
              data-testid={`kb-preview-retrieved-item-${r.id}`}
            >
              {r.title || "(untitled)"}
              {typeof r.score === "number" ? (
                <span style={{ opacity: 0.7 }}>· {r.score}</span>
              ) : null}
            </span>
          ))}
        </div>
      )}
      {error ? (
        <div className="text-xs" style={{ color: "#B91C1C" }}
             data-testid="kb-preview-error">
          {error}
        </div>
      ) : (
        <pre
          className="text-[11px] font-mono whitespace-pre-wrap max-h-64 overflow-y-auto p-2 rounded"
          style={{
            backgroundColor: colors.surfaceSecondary,
            color: colors.onSurface,
            border: `1px solid ${colors.border}`,
          }}
          data-testid="kb-preview-body"
        >
          {data?.system_prompt || ""}
        </pre>
      )}
    </div>
  );
}


// ═══════════════════════════════════════════════════════════════════
// Phase P3 · Feb-2026 · Deliverable 2 — Knowledge Library.
//
// Client-side grid over the KB rows already loaded on the page.
// Only rows with ``source_file_id`` are shown (uploaded manuals).
// View / Supersede / Delete per card.  Search matches title + tags
// + the leading slice of content_md.  Sorted newest first.
// ═══════════════════════════════════════════════════════════════════
function KnowledgeLibrarySection({ items, onSupersede, onDelete }) {
  const [search, setSearch] = React.useState("");
  const libraryItems = React.useMemo(() => {
    const base = (items || []).filter((r) => r && r.source_file_id);
    const q = search.trim().toLowerCase();
    let filtered = base;
    if (q) {
      filtered = base.filter((r) => {
        const hay = [
          r.title, (r.tags || []).join(" "),
          (r.content_md || "").slice(0, 500),
        ].filter(Boolean).join(" ").toLowerCase();
        return hay.includes(q);
      });
    }
    return [...filtered].sort((a, b) => (
      (b.created_at || "").localeCompare(a.created_at || "")
    ));
  }, [items, search]);

  return (
    <div className="rounded-xl p-3 mt-3"
         style={{ backgroundColor: colors.surface, border: `1px solid ${colors.border}` }}
         data-testid="kb-library-section">
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
        <div>
          <div className="text-sm font-semibold" style={{ color: colors.onSurface }}>
            Knowledge Library
          </div>
          <div className="text-[11px]" style={{ color: colors.muted }}>
            Uploaded manuals (PDF · DOCX · TXT · MD).
          </div>
        </div>
        <input
          type="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search title, tags, content…"
          className="text-sm rounded-md px-2 py-1.5 w-full sm:w-72"
          style={{
            backgroundColor: colors.surfaceSecondary,
            color: colors.onSurface,
            border: `1px solid ${colors.border}`,
          }}
          data-testid="kb-library-search"
        />
      </div>
      {libraryItems.length === 0 ? (
        <div className="text-xs p-4 text-center"
             style={{ color: colors.muted }}
             data-testid="kb-library-empty">
          No uploaded manuals yet — use the Upload button to add one.
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2"
             data-testid="kb-library-grid">
          {libraryItems.map((r) => (
            <div
              key={r.id}
              className="rounded-lg p-3"
              style={{
                backgroundColor: colors.surfaceSecondary,
                border: `1px solid ${colors.border}`,
              }}
              data-testid={`kb-library-card-${r.id}`}
            >
              <div className="flex items-start justify-between gap-2">
                <div className="text-sm font-semibold truncate"
                     style={{ color: colors.onSurface }}>
                  {r.title}
                </div>
                {r.source_type ? (
                  <span
                    className="shrink-0 px-1.5 py-0.5 rounded text-[9px] font-semibold uppercase"
                    style={{ backgroundColor: colors.brandTertiary, color: colors.brand }}
                    data-testid={`kb-library-badge-${r.id}`}
                  >{r.source_type}</span>
                ) : null}
              </div>
              <div className="text-[10px] mt-0.5" style={{ color: colors.muted }}>
                {(r.created_at || "").slice(0, 10)}
                {r.tags && r.tags.length > 0 ? ` · ${r.tags.join(", ")}` : ""}
              </div>
              <div className="mt-2 flex items-center gap-2 text-[11px]">
                <a
                  href={`/api/files/${r.source_file_id}/download`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="underline"
                  style={{ color: colors.brand }}
                  data-testid={`kb-library-view-${r.id}`}
                >View original</a>
                <button
                  type="button"
                  onClick={() => onSupersede?.(r)}
                  className="underline"
                  style={{ color: colors.brand }}
                  data-testid={`kb-library-supersede-${r.id}`}
                >Supersede</button>
                <button
                  type="button"
                  onClick={() => onDelete?.(r)}
                  className="underline"
                  style={{ color: "#B91C1C" }}
                  data-testid={`kb-library-delete-${r.id}`}
                >Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

